{
  "root_causes": [
    {
      "service": "ts-contacts-service",
      "fault_kind": "network_loss",
      "evidence": [
        {"kind": "metric", "sql": "SELECT metric, attr_source, attr_destination, SUM(value) AS total FROM abnormal_metrics_sum WHERE metric='hubble_drop_total' AND attr_source LIKE '%ts-contacts-service%' AND attr_destination LIKE '%ts-preserve-service%' GROUP BY 1,2,3", "claim": "Hubble drop counter on the contacts-to-preserve connection totals 40 drops in the abnormal window; none appear in normal."},
        {"kind": "trace", "sql": "SELECT quantile_cont(c.duration,0.5)/1e6 AS caller_p50_ms, quantile_cont(c.duration,0.95)/1e6 AS caller_p95_ms, quantile_cont(s.duration,0.5)/1e6 AS callee_p50_ms, quantile_cont(s.duration,0.95)/1e6 AS callee_p95_ms, COUNT(*) n FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id WHERE c.service_name='ts-preserve-service' AND c.attr_span_kind='Client' AND s.service_name='ts-contacts-service'", "claim": "Preserve's GET calls to contacts take ~1.7 s p50 and ~53 s p95, while contacts' server spans stay at ~7-10 ms."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-contacts-service", "to": "ts-preserve-service", "evidence": [{"kind": "trace", "sql": "SELECT c.span_name, COUNT(*) n, quantile_cont(c.duration,0.95)/1e6 AS caller_p95_ms, quantile_cont(s.duration,0.95)/1e6 AS callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id WHERE c.service_name='ts-preserve-service' AND c.attr_span_kind='Client' AND s.service_name='ts-contacts-service' GROUP BY 1", "claim": "The slow leg is the preserve-to-contacts GET, where caller time far exceeds callee time, so the delay sits in the network."}]},
    {"from": "ts-preserve-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT 'ui_to_preserve' k, COUNT(*) n, quantile_cont(c.duration,0.95)/1e6 AS p95_ms FROM abnormal_traces c WHERE c.service_name='ts-ui-dashboard' AND c.span_name LIKE 'POST /api/v1/preserveservice%'", "claim": "User-facing preserve requests at ui-dashboard reach p95 ~20 s in the abnormal window; preserve server p50 rose from 180 ms to 2.6 s."}]}
  ]
}
